        asm.recipe(MachineRecipe.of().in(I("rocket_kit_qiming_1_1"), 1).in(I("rocket_kit_qiming_1_2"), 1).in(I("crew_capsule"), 1).in(I("nose_cone"), 1).in(I("escape_tower"), 1).out(I("rocket_qiming_1")).time(1200).power(240));
