        asm.recipe(MachineRecipe.of().in(I("rocket_kit_titan_explorer_1"), 1).in(I("rocket_kit_titan_explorer_2"), 1).in(I("rocket_kit_titan_explorer_3"), 1).in(I("crew_capsule"), 1).in(I("nose_cone"), 1).in(I("escape_tower"), 1).out(I("rocket_titan_explorer")).time(1200).power(240));
        asm.recipe(MachineRecipe.of().in(I("rocket_kit_horizon_x_1"), 1).in(I("rocket_kit_horizon_x_2"), 1).in(I("crew_capsule"), 1).in(I("nose_cone"), 1).in(I("escape_tower"), 1).out(I("rocket_horizon_x")).time(1200).power(240));
